using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private readonly string baseUrl;

    private HttpStatusCode replyStatus = HttpStatusCode.OK;
    private string replyBody = """{"status":"approved"}""";
    private string? receivedMethod;
    private string? receivedPath;
    private string? receivedContentType;
    private string? receivedBody;

    public HttpPaymentGatewayTests()
    {
        var port = FreePort();
        baseUrl = $"http://127.0.0.1:{port}";
        listener.Prefixes.Add(baseUrl + "/");
        listener.Start();
        _ = Task.Run(Serve);
        client = new HttpClient { BaseAddress = new Uri(baseUrl) };
    }

    [Fact]
    public async Task The_authorization_is_posted_as_json_with_reference_amount_and_currency()
    {
        await new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);

        Assert.Equal("POST", receivedMethod);
        Assert.Equal("/v1/authorizations", receivedPath);
        Assert.StartsWith("application/json", receivedContentType);
        using var json = JsonDocument.Parse(receivedBody!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_status_is_read_as_approved()
    {
        replyBody = """{"status":"approved"}""";

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_status_is_read_as_declined()
    {
        replyBody = """{"status":"declined"}""";

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Unknown_fields_in_the_answer_are_ignored()
    {
        replyBody = """{"id":"auth_1","status":"approved","risk":{"score":3}}""";

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_is_a_decline_even_with_an_error_body()
    {
        replyStatus = HttpStatusCode.PaymentRequired;
        replyBody = """{"error":"insufficient_funds"}""";

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_is_a_decline_with_an_empty_body()
    {
        replyStatus = HttpStatusCode.PaymentRequired;
        replyBody = "";

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(HttpStatusCode.BadRequest)]
    [InlineData(HttpStatusCode.Unauthorized)]
    [InlineData(HttpStatusCode.InternalServerError)]
    [InlineData(HttpStatusCode.ServiceUnavailable)]
    public async Task Other_failures_are_raised_rather_than_treated_as_a_decision(HttpStatusCode status)
    {
        replyStatus = status;
        replyBody = """{"status":"approved"}""";

        await Assert.ThrowsAsync<HttpRequestException>(Authorize);
    }

    [Fact]
    public async Task An_unrecognised_status_is_never_read_as_approved()
    {
        replyBody = """{"status":"pending"}""";

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task An_answer_without_a_status_is_never_read_as_approved()
    {
        replyBody = """{"result":"approved"}""";

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_body_that_is_not_json_is_raised()
    {
        replyBody = "<html>gateway error</html>";

        await Assert.ThrowsAnyAsync<JsonException>(Authorize);
    }

    private Task<AuthorizationOutcome> Authorize() =>
        new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", new Money(12m, "EUR"), CancellationToken.None);

    private async Task Serve()
    {
        while (listener.IsListening)
        {
            HttpListenerContext context;
            try { context = await listener.GetContextAsync(); }
            catch (Exception) { return; }

            receivedMethod = context.Request.HttpMethod;
            receivedPath = context.Request.Url!.AbsolutePath;
            receivedContentType = context.Request.ContentType;
            using (var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8))
                receivedBody = await reader.ReadToEndAsync();

            var bytes = Encoding.UTF8.GetBytes(replyBody);
            context.Response.StatusCode = (int)replyStatus;
            context.Response.ContentType = "application/json";
            context.Response.ContentLength64 = bytes.Length;
            await context.Response.OutputStream.WriteAsync(bytes);
            context.Response.Close();
        }
    }

    private static int FreePort()
    {
        var probe = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        probe.Start();
        var port = ((IPEndPoint)probe.LocalEndpoint).Port;
        probe.Stop();
        return port;
    }

    public void Dispose()
    {
        listener.Close();
        client.Dispose();
    }
}
